basic.code:
type User {
  id: ID!
  name: String!
}

type Query {
  user(id: ID!): User
}

mutation UpdateName {
  updateUser(id: "1", name: "Ava") {
    id
    name
  }
}

query GetUser($id: ID!) {
  user(id: $id) {
    id
    name
  }
}

type User {
  id: ID!
  name: String
}

query {
  user {
    name
  }
}

query {
  recent: posts(limit: 5) { id }
  popular: posts(limit: 5, sort: POPULAR) { id }
}

fragment UserCard on User {
  id
  name
}

query {
  me {
    ...UserCard
  }
}

